  if (!entities) return new Map();
  const map = new Map(); // guid -> entity
  entities.forEach(e => map.set(e.guid, e));

  // Find root for each entity
  function findRoot(guid) {
    const e = map.get(guid);
    if (!e || !e.parent?.guid) return guid;
    return findRoot(e.parent.guid);
  }

  // Find which roots have children
