  let changed = false;
  arr.forEach(item => {
    if (item && item.parent !== undefined) { delete item.parent; changed = true; }
  });
  return changed;
}

const files = fs.readdirSync(dir).filter(f => f.endsWith(".json"));
files.forEach(f => {
  const filePath = path.join(dir, f);
  const content = fs.readFileSync(filePath, "utf8");
  if (content.indexOf('"parent"') === -1) return;
  const obj = JSON.parse(content);
  let changed = false;
  if (Array.isArray(obj.types) && obj.types.some(t => t.parent)) { processEntities(obj.types); changed = true; }
  if (Array.isArray(obj.designs) && obj.designs.some(d => d.parent)) { processEntities(obj.designs); changed = true; }
  if (obj.forward) {
    if (processDiffArray(obj.forward.types)) changed = true;
    if (processDiffArray(obj.forward.designs)) changed = true;
  }
  if (obj.backward) {
    if (processDiffArray(obj.backward.types)) changed = true;
    if (processDiffArray(obj.backward.designs)) changed = true;
  }
  if (changed) {
    fs.writeFileSync(filePath, JSON.stringify(obj, null, 2) + "\n");
    console.log("Updated:", f);
  }
});
