  console.error("[DEBUG] designs count:", kitI.designs?.length, "vs", deserializedKit.designs?.length);
  for (const t of kitI.types ?? []) {
    const dt = deserializedKit.types?.find((x: any) => x.guid === t.guid);
    if (!dt) { console.error("[DEBUG] type missing after roundtrip:", t.name, t.guid); continue; }
    if (t.name !== dt.name) console.error("[DEBUG] type name diff:", t.name, "vs", dt.name);
    const fa = t.families ?? [];
    const fb = dt.families ?? [];
    if (fa.length !== fb.length || !fa.every((f: string) => fb.includes(f))) console.error("[DEBUG] type families diff:", t.name, fa, "vs", fb);
  }
  for (const d of kitI.designs ?? []) {
    const dd = deserializedKit.designs?.find((x: any) => x.guid === d.guid);
    if (!dd) { console.error("[DEBUG] design missing after roundtrip:", d.name, d.guid); continue; }
    if (d.name !== dd.name) console.error("[DEBUG] design name diff:", d.name, "vs", dd.name);
    const fa = d.families ?? [];
    const fb = dd.families ?? [];
    if (fa.length !== fb.length || !fa.every((f: string) => fb.includes(f))) console.error("[DEBUG] design families diff:", d.name, fa, "vs", fb);
  }
}
