const fs=require('fs');
const kit=JSON.parse(fs.readFileSync('./semio/assets/semio/metabolism.kit.semio.json','utf8'));

// Design families fix:
// Main designs are fine (NCT, Slanted, Twisted, Dancing have unique names in NCT family)
// Flat designs need unique families matching their source design
// Flat designs: 5 total (one per flatten case)
// - Flat of NCT: 180 pieces, conns=0
// - Flat of Slanted: 180 pieces, conns=0
// - Flat of Twisted: 180 pieces, conns=0
// - Flat of Dancing: 180 pieces, conns=0
// - Flat of Capsule Dream: 2880 pieces, conns=0

// Determine which Flat belongs to which source by checking piece types
const variants = {
  'Nakagin Capsule Tower': kit.designs.find(d => d.name === 'Nakagin Capsule Tower'),
  'Slanted': kit.designs.find(d => d.name === 'Slanted'),
  'Twisted': kit.designs.find(d => d.name === 'Twisted'),
  'Dancing': kit.designs.find(d => d.name === 'Dancing'),
  'Capsule Dream': kit.designs.find(d => d.name === 'Capsule Dream'),
};

const flats = kit.designs.filter(d => d.name === 'Flat');
console.log('Flat designs:', flats.length);

flats.forEach(flat => {
  // Match to source by piece type set overlap
  const flatTypeGuids = new Set(flat.pieces?.map(p => p.type?.guid).filter(Boolean) || []);

  let bestMatch = null;
  let bestOverlap = 0;

  for (const [name, src] of Object.entries(variants)) {
    if (!src) continue;
    const srcTypeGuids = new Set(src.pieces?.map(p => p.type?.guid).filter(Boolean) || []);
    let overlap = 0;
    for (const g of flatTypeGuids) {
      if (srcTypeGuids.has(g)) overlap++;
    }
    // Also check piece count match
    const pieceCountMatch = flat.pieces?.length === src.pieces?.length;
    if (overlap > bestOverlap || (overlap === bestOverlap && pieceCountMatch)) {
      bestOverlap = overlap;
      bestMatch = name;
    }
  }

  console.log('Flat ' + flat.guid.substring(0, 8) + ' (' + flat.pieces?.length + ' pieces) => ' + bestMatch);
  flat.families = [bestMatch];
});

// Verify uniqueness
const nc = {};
kit.designs.forEach(d => {
  const k = d.name + '|' + JSON.stringify(d.families);
  nc[k] = (nc[k] || 0) + 1;
});
Object.entries(nc).filter(([k, v]) => v > 1).forEach(([k, v]) => console.log('DUP:', k, 'x' + v));
console.log('Unique design name+family:', Object.keys(nc).length, '/', kit.designs.length);

fs.writeFileSync('./semio/assets/semio/metabolism.kit.semio.json', JSON.stringify(kit, null, 2) + '\n');
console.log('Saved.');
