node -e "
const fs=require('fs');
const kit=JSON.parse(fs.readFileSync('./semio/assets/semio/metabolism.kit.semio.json','utf8'));

// Build type→design usage map
const dNames=['Nakagin Capsule Tower','Slanted','Twisted','Dancing','Capsule Dream'];
const dTypes={};
dNames.forEach(dn=>{
  const d=kit.designs.find(x=>x.name===dn);
  dTypes[dn]=new Set(d.pieces.map(p=>p.type?.guid).filter(Boolean));
});

// Find all types with duplicate name+family
const nameCount={};
kit.types.forEach(t=>{
  const key=t.name+'|'+JSON.stringify(t.families);
  nameCount[key]=(nameCount[key]||0)+1;
});
const dupKeys=new Set(Object.keys(nameCount).filter(k=>nameCount[k]>1));

// For duplicate types, find which design variant they belong to
// The connector types (\\, /, q, p, J, L, s, z) belong to specific capsule shape parents
// We know: capsule shape parents are Capsule, Ellipsoid, Trapezoid, Balcony
// Mapping from design variant to capsule shape:
// We need to figure out which parent type each design's connector types came from

// For NCT: connector types used in NCT → parent was Capsule (the main capsule type)
// But we don't know the exact capsule-to-design mapping
// Instead, let's use the design name as the family for connector types

const variants=['Nakagin Capsule Tower','Slanted','Twisted','Dancing'];
let changed=0;
kit.types.forEach(t=>{
  const key=t.name+'|'+JSON.stringify(t.families);
  if(!dupKeys.has(key)) return;

  // Find which design variant exclusively uses this type
  const usedIn=variants.filter(dn=>dTypes[dn]?.has(t.guid));

  if(usedIn.length===1){
    // Connector type used by exactly one variant → use that variant's name as family
    t.families=[usedIn[0]];
    changed++;
  } else if(usedIn.length>1){
    // Used by multiple variants (e.g., First Storey, Last Storey)
    // Group: NCT+Slanted share one set, Twisted+Dancing share another
    // Use first design name as family
    t.families=[usedIn[0]];
    changed++;
  } else {
    // Unused type - keep as is but needs unique family
    // These are q, z, Single Storey variants that aren't referenced
  }
});

// Handle unused duplicate types (q, z, Single Storey)
// They were children of capsule variants but unused in designs
// Assign parent capsule type names
const capsuleShapes=['Capsule','Ellipsoid','Trapezoid','Balcony'];
const unusedGroups={};
kit.types.forEach(t=>{
  const key=t.name+'|'+JSON.stringify(t.families);
  if(!dupKeys.has(key)) return;
  const usedIn=variants.filter(dn=>dTypes[dn]?.has(t.guid));
  if(usedIn.length===0){
    if(!unusedGroups[t.name]) unusedGroups[t.name]=[];
    unusedGroups[t.name].push(t);
  }
});

// Assign capsule shape names to unused types
Object.entries(unusedGroups).forEach(([name,types])=>{
  types.forEach((t,i)=>{
    if(i<capsuleShapes.length){
      t.families=[capsuleShapes[i]];
      changed++;
    }
  });
});

// Also handle Tambour variants
// First/Last/Single Storey duplicates
// Group: NCT+Slanted use one set, Twisted+Dancing use another
const tambourVariants=['Tambour','Small Tambour'];
kit.types.filter(t=>t.families?.includes('Tambour')).forEach(t=>{
  const usedIn=variants.filter(dn=>dTypes[dn]?.has(t.guid));
  const key=t.name+'|'+JSON.stringify(t.families);
  if(dupKeys.has(key)){
    if(usedIn.includes('Nakagin Capsule Tower')||usedIn.includes('Slanted')){
      t.families=['Tambour'];
    } else if(usedIn.includes('Twisted')||usedIn.includes('Dancing')){
      t.families=['Small Tambour'];
    }
    changed++;
  }
});

console.log('Changed:', changed, 'types');

// Verify no more duplicates
const newNameCount={};
kit.types.forEach(t=>{
  const key=t.name+'|'+JSON.stringify(t.families);
  newNameCount[key]=(newNameCount[key]||0)+1;
});
const remaining=Object.entries(newNameCount).filter(([k,v])=>v>1);
remaining.forEach(([k,v])=>console.log('STILL DUP:', k, 'x'+v));

fs.writeFileSync('./semio/assets/semio/metabolism.kit.semio.json', JSON.stringify(kit,null,2)+'\n');
console.log('Saved.');
"

