const fs=require('fs');
const fp='semio/assets/semio/metabolism.kit.diff.semio.json';
const d=JSON.parse(fs.readFileSync(fp,'utf8'));

// Remove parent from all type diffs and design diffs
const removeParent = obj => {
  if(!obj || typeof obj !== 'object') return;
  if(Array.isArray(obj)){obj.forEach(removeParent);return;}
  delete obj.parent;
  Object.values(obj).forEach(removeParent);
};

// Actually we need to be more careful - only remove parent from type/design diffs
// and add families where needed
if(d.types?.updated){
  d.types.updated.forEach(u=>{
    if(u.diff){
      delete u.diff.parent;
    }
  });
}
if(d.designs?.updated){
  d.designs.updated.forEach(u=>{
    if(u.diff){
      delete u.diff.parent;
    }
  });
}

// Check for any remaining parent refs
const content = JSON.stringify(d);
console.log('Has parent:', content.includes('\"parent\"'));

fs.writeFileSync(fp, JSON.stringify(d,null,2)+'\n');
console.log('Saved diff');

